import{_ as o,o as t,c as r,a2 as a}from"./chunks/framework.BXzK3EA4.js";const m=JSON.parse('{"title":"Voice Based Orders","description":"","frontmatter":{},"headers":[],"relativePath":"trading-platform/python/voice-based-orders.md","filePath":"trading-platform/python/voice-based-orders.md"}'),s={name:"trading-platform/python/voice-based-orders.md"};function i(n,e,d,c,p,l){return t(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="voice-based-orders" tabindex="-1">Voice Based Orders <a class="header-anchor" href="#voice-based-orders" aria-label="Permalink to &quot;Voice Based Orders&quot;">​</a></h1><p>This is an experimental feature using Tradeboard &amp; Groq (Whisper Large V3 Model). This system allows users to place orders via voice commands. The voice commands are translated from speech to text using the OpenAI Whisper large v3 model, and then the transcription is fed to Tradeboard to execute the order.</p><p><a href="https://github.com/wesoftcorp/tradeboard-docs-voice-based-orders" target="_blank" rel="noreferrer">https://github.com/wesoftcorp/tradeboard-docs-voice-based-orders</a></p><p><strong>How to Use the Tradeboard Voice-Based Trading System</strong></p><ol><li>Select the desired Exchange and Product Type from the dropdown menus.</li><li>Click the &quot;Start Listening&quot; button to begin.</li><li>Speak your command clearly (e.g., &quot;Milo buy 20 TCS&quot;).</li><li>After a brief pause, your order will be processed automatically.</li><li>To stop listening, click the &quot;Stop Listening&quot; button.</li></ol><p><strong>Supported Activation Commands:</strong> MILO, MYLO</p><p><strong>Exchanges Supported:</strong> NSE, BSE</p><p><strong>Product Types:</strong> MIS (Margin Intraday Square off), CNC (Cash and Carry for equity)</p><p><strong>Setting up Groq and Tradeboard API keys:</strong></p><ol><li>Go to <a href="https://console.groq.com" target="_blank" rel="noreferrer">console.groq.com</a></li><li>Create an API key and copy it to your clipboard.</li><li>In your Tradeboard application, go to &quot;API Key&quot;. Get your Tradeboard API Key.</li></ol><p><strong>Dictionary Mapping</strong></p><p>To ensure that the system correctly interprets voice commands, it uses a dictionary mapping. This dictionary maps common stock names and abbreviations to their corresponding symbols.</p><p>The system automatically extracts the action, quantity, and symbol from the voice command and then places the order. In the logs, you&#39;ll find details such as the order ID, timestamp, and response data.</p><p><strong>Overall Assessment</strong></p><p>This experimental voice-based trading system offers a novel approach to order placement. Although there is room for improvement, such as enhancing the accuracy of speech-to-text transcription and refining the natural language understanding capabilities, this initiative showcases the potential of using AI technologies in the financial trading space.</p>',15)])])}const g=o(s,[["render",i]]);export{m as __pageData,g as default};
